  var cv = $("welt"), W = 0, H = 0, DPR = 1, gl = null, c = null, U = {}, ZAHL = 0;
  try { gl = cv.getContext("webgl", { antialias: true, alpha: false, powerPreference: "low-power" }); } catch (e) { gl = null; }
